class Jeu:
    def __init__(self, titre, nb_min, nb_max):
        self.titre = titre
        self.nb_min = nb_min
        self.nb_max = nb_max
        self.disponible = True

    def convient(self, n):
        return self.disponible and self.nb_min <= n <= self.nb_max

def jeux_possibles(liste_jeux, n):
    return [j.titre for j in liste_jeux if j.convient(n)]
